from pathlib import Path
import base64
import gzip
import subprocess

p = Path("app/src/App.tsx")
s = p.read_text(encoding="utf-8")
old = '<BingoBookOverlay s={s} onChanged={force} onClose={() => setBingoBookOpen(false)} />'
new = '<BingoBookOverlay s={s} onChanged={() => { if (sRef.current.phase !== "paused") setBingoBookOpen(false); force(); }} onClose={() => setBingoBookOpen(false)} />'
if old not in s:
    if new in s:
        print("Bingo Book v7.1 battle-close fix already applied")
    else:
        raise SystemExit("Bingo Book v7.1 App anchor not found")
else:
    p.write_text(s.replace(old, new, 1), encoding="utf-8")
    print("Bingo Book v7.1 battle-close fix applied")

subprocess.run(["python", "overrides/apply_bingo_book_v8_mobile.py"], check=True)

# Final mainline polish, intentionally applied after the full v16 + Bingo stack.
# It is generated against the latest successful main patched-source snapshot.
POLISH_PATCH_GZ_B64 = ""
patch_bytes = gzip.decompress(base64.b64decode(POLISH_PATCH_GZ_B64))
subprocess.run(["patch", "-p1", "--batch", "--forward"], cwd="app", input=patch_bytes, check=True)

sw = Path("app/public/sw.js")
sw_text = sw.read_text(encoding="utf-8")
old_cache = 'const CACHE = "shadow-village-bingo-book-v8-mobile-polish";'
new_cache = 'const CACHE = "shadow-village-main-polish-v1";'
if old_cache in sw_text:
    sw.write_text(sw_text.replace(old_cache, new_cache, 1), encoding="utf-8")
elif new_cache not in sw_text:
    raise SystemExit("Main polish cache anchor not found")

print("Main polish applied: centred ninja profiles, narrower mobile HUD, audited/replaced obsolete technique-tree nodes")
